#include <vector>
#include <omp.h>

void prefixSum(std::vector<double> const& x, std::vector<double> &output) {
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) return;

    int nt = 1;
#pragma omp parallel
    {
#pragma omp single
        nt = omp_get_num_threads();
    }

    std::vector<double> blockSums(static_cast<std::size_t>(nt), 0.0);

#pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int T = omp_get_num_threads();

        const std::size_t start = (static_cast<std::size_t>(tid) * n) / static_cast<std::size_t>(T);
        const std::size_t end   = (static_cast<std::size_t>(tid + 1) * n) / static_cast<std::size_t>(T);

        // Local prefix within each block
        double sum = 0.0;
        for (std::size_t i = start; i < end; ++i) {
            sum += x[i];
            output[i] = sum;
        }

        // Each thread writes its block total to a unique slot
        blockSums[static_cast<std::size_t>(tid)] = sum;

#pragma omp barrier

        // Compute offset = sum of all previous block sums
        double offset = 0.0;
        for (int t = 0; t < tid; ++t) {
            offset += blockSums[static_cast<std::size_t>(t)];
        }

        // Add offset to this block's outputs
        if (offset != 0.0) {
            for (std::size_t i = start; i < end; ++i) {
                output[i] += offset;
            }
        }
    }
}
